void ui_event_muyuplay(lv_event_t *e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t *target = lv_event_get_target(e);
    if (event_code == LV_EVENT_SCREEN_LOAD_START)
    {
        lv_obj_set_parent(ui_title_page, ui_muyu_page);

        gongde_sum = 0;
        gongdeyuanman = 0;
        lv_label_set_text_fmt(ui_muyu_gongde_sum, "#f1c40f 今日功德: %d#", gongde_sum);
        opaon_Animation(ui_muyu_gongde_sum, 0);
    }
    if (event_code == LV_EVENT_UP_CLICK || event_code == LV_EVENT_DOWN_CLICK)
    {
        gonde_txt_Animation(ui_muyu_gongdetxt, 0);
        gongde_sum = (gongde_sum < GONGDE_THRESHOLD + 5) ? gongde_sum + 1 : GONGDE_THRESHOLD + 5;
        if (gongdeyuanman == 5) // 第五次了，切换到摸鱼页面
        {
            _ui_screen_change(&ui_fish_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_fish_screen_init);
            return;
        }
        if (gongde_sum >= GONGDE_THRESHOLD)
        {
            if (gongde_sum == GONGDE_THRESHOLD)
                gongdeyuanman = 0;
            gongdeyuanman++;
            muyushow_Animation(ui_muyu_img, 0);
            char *src = "!!!!!";
            char src_num[6] = "";
            strncpy(src_num, src, gongdeyuanman);
            lv_label_set_text_fmt(ui_muyu_gongde_sum, "#f1c40f 功德圆满%s#", src_num);
            uint8_t event_code = UI_EVENT_AUDIO_PLAY_MUYU;
            xQueueSend(ui_send_event, &event_code, 0);

        }
        else
        {
            muyushow_Animation(ui_muyu_img, 0);
            lv_label_set_text_fmt(ui_muyu_gongde_sum, "#f1c40f 今日功德: %d/%d#", gongde_sum, GONGDE_THRESHOLD);
            uint8_t event_code = UI_EVENT_AUDIO_PLAY_MUYU;
            xQueueSend(ui_send_event, &event_code, 0);
        }
    }
    if (event_code == LV_EVENT_LEFT_CLICK)
    {
        _ui_screen_change(&ui_face_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_face_screen_init);
    }
    if (event_code == LV_EVENT_RIGHT_CLICK)
    {
        _ui_screen_change(&ui_game_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_game_screen_init);
    }

}
